//! PHP's bundled timezone database (`timezonedb.h`), loaded from `data/tzdb.bin`.
//!
//! The asset is generated by `examples/gen_tzdb.rs`; see that file for the format and
//! the regeneration command.

use std::cmp::Ordering;
use std::sync::OnceLock;

static TZDB_BIN: &[u8] = include_bytes!("../../data/tzdb.bin");

/// One entry of the database index (`timelib_tzdb_index_entry`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TzIndexEntry {
    /// The identifier, e.g. `Europe/Amsterdam`.
    pub id: String,
    /// Offset of the zone's data in [`TzDb::data`].
    pub pos: usize,
}

/// A timezone database (`timelib_tzdb`).
#[derive(Debug)]
pub struct TzDb {
    version: String,
    index: Vec<TzIndexEntry>,
    data: &'static [u8],
}

fn be_u16(b: &[u8], p: usize) -> u16 {
    u16::from_be_bytes([b[p], b[p + 1]])
}

fn be_u32(b: &[u8], p: usize) -> u32 {
    u32::from_be_bytes([b[p], b[p + 1], b[p + 2], b[p + 3]])
}

impl TzDb {
    fn load(bin: &'static [u8]) -> TzDb {
        assert_eq!(&bin[..8], b"PHPTZDB1", "corrupt tzdb.bin");
        let mut p = 8;
        let vlen = usize::from(be_u16(bin, p));
        p += 2;
        let version = String::from_utf8_lossy(&bin[p..p + vlen]).into_owned();
        p += vlen;
        let count = be_u32(bin, p) as usize;
        p += 4;
        let mut index = Vec::with_capacity(count);
        for _ in 0..count {
            let len = usize::from(bin[p]);
            p += 1;
            let id = String::from_utf8_lossy(&bin[p..p + len]).into_owned();
            p += len;
            let pos = be_u32(bin, p) as usize;
            p += 4;
            index.push(TzIndexEntry { id, pos });
        }
        let dlen = be_u32(bin, p) as usize;
        p += 4;
        TzDb {
            version,
            index,
            data: &bin[p..p + dlen],
        }
    }

    /// Database version, e.g. `"2026.5"` (`timezone_version_get()`).
    pub fn version(&self) -> &str {
        &self.version
    }

    /// The sorted identifier index (`timelib_timezone_identifiers_list`).
    pub fn identifiers(&self) -> &[TzIndexEntry] {
        &self.index
    }

    /// Raw zone data blob.
    pub fn data(&self) -> &'static [u8] {
        self.data
    }

    /// Zone data for an index entry.
    pub fn entry_data(&self, entry: &TzIndexEntry) -> &'static [u8] {
        &self.data[entry.pos..]
    }

    /// Whether the entry's "BC" flag is set (the zone is a canonical, non-backwards
    /// compatible identifier); used by `DateTimeZone::listIdentifiers()`.
    pub fn entry_is_bc(&self, entry: &TzIndexEntry) -> bool {
        self.data.get(entry.pos + 4) == Some(&1)
    }

    /// Two letter ISO 3166 country code of an entry (`"??"` if unknown).
    pub fn entry_country_code(&self, entry: &TzIndexEntry) -> [u8; 2] {
        [
            self.data.get(entry.pos + 5).copied().unwrap_or(b'?'),
            self.data.get(entry.pos + 6).copied().unwrap_or(b'?'),
        ]
    }

    /// Case-insensitive binary search for an identifier (`seek_to_tz_position`).
    pub fn find(&self, timezone: &str) -> Option<&TzIndexEntry> {
        if self.index.is_empty() {
            return None;
        }
        let (mut left, mut right) = (0isize, self.index.len() as isize - 1);
        while left <= right {
            let mid = ((left + right) as usize) >> 1;
            match strcasecmp(timezone.as_bytes(), self.index[mid].id.as_bytes()) {
                Ordering::Less => right = mid as isize - 1,
                Ordering::Greater => left = mid as isize + 1,
                Ordering::Equal => return Some(&self.index[mid]),
            }
        }
        None
    }

    /// Whether `timezone` is a known identifier (`timelib_timezone_id_is_valid`).
    pub fn is_valid(&self, timezone: &str) -> bool {
        self.find(timezone).is_some()
    }
}

/// `timelib_strcasecmp` ordering (ASCII case folding, byte comparison).
pub(crate) fn strcasecmp(a: &[u8], b: &[u8]) -> Ordering {
    for (x, y) in a.iter().zip(b.iter()) {
        let (x, y) = (x.to_ascii_lowercase(), y.to_ascii_lowercase());
        if x != y {
            return x.cmp(&y);
        }
    }
    a.len().cmp(&b.len())
}

/// The bundled database (`timelib_builtin_db`).
pub fn builtin_db() -> &'static TzDb {
    static DB: OnceLock<TzDb> = OnceLock::new();
    DB.get_or_init(|| TzDb::load(TZDB_BIN))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn index_loads() {
        let db = builtin_db();
        assert_eq!(db.version(), "2026.5");
        assert_eq!(db.identifiers().len(), 598);
        assert!(db.is_valid("europe/amsterdam"));
        assert!(db.is_valid("UTC"));
        assert!(!db.is_valid("Mars/Olympus"));
        let e = db.find("Europe/Amsterdam").unwrap();
        assert_eq!(&db.entry_country_code(e), b"NL");
        assert!(db.entry_is_bc(e));
    }
}
